fn accept_bounded(listener:&TcpListener)->Result<TcpStream>{listener.set_nonblocking(true)?;let end=Instant::now()+Duration::from_secs(15);loop{match listener.accept(){Ok((s,_))=>{s.set_nonblocking(false)?;return Ok(s)},Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>{ensure!(Instant::now()<end,"owned producer accept deadline");thread::sleep(Duration::from_millis(2));},Err(e)=>return Err(e.into())}}}
